import React, { useState } from 'react';

const QuizConfigPage = () => {
  const [subjects, setSubjects] = useState('');
  const [difficulty, setDifficulty] = useState('easy');
  const [examInfo, setExamInfo] = useState('');
  const [questionType, setQuestionType] = useState('multipleChoice');
  const [timeLimit, setTimeLimit] = useState(60); // Default to 60 seconds
  const [numQuestions, setNumQuestions] = useState(10); // Default to 10 questions
  const [includeHint, setIncludeHint] = useState(false);
  const [customKeywords, setCustomKeywords] = useState('');
  const [studyMaterialType, setStudyMaterialType] = useState('Books');
  const [formSubmitted, setFormSubmitted] = useState(false);

  const handleSubjectChange = (e) => setSubjects(e.target.value);
  const handleDifficultyChange = (e) => setDifficulty(e.target.value);
  const handleExamInfoChange = (e) => setExamInfo(e.target.value);
  const handleQuestionTypeChange = (e) => setQuestionType(e.target.value);
  const handleTimeLimitChange = (e) => setTimeLimit(e.target.value);
  const handleNumQuestionsChange = (e) => setNumQuestions(e.target.value);
  const handleIncludeHintChange = () => setIncludeHint((prev) => !prev);
  const handleKeywordsChange = (e) => setCustomKeywords(e.target.value);
  const handleStudyMaterialChange = (e) => setStudyMaterialType(e.target.value);

  const handleSubmit = (e) => {
    e.preventDefault();
    setFormSubmitted(true);
  };

  return (
    <div className="container mx-auto p-6">
      <h1 className="text-3xl font-bold mb-6 text-center">Personalized Quiz Generator</h1>
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
          <label htmlFor="subjects" className="block text-lg font-semibold">Enter Subjects:</label>
          <input
            type="text"
            id="subjects"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={subjects}
            onChange={handleSubjectChange}
            placeholder="E.g., Physics, Math, Chemistry"
            required
          />
          <p className="text-gray-500 text-sm mt-1">Separate subjects with commas (e.g., Math, Physics, Chemistry).</p>
        </div>

        <div className="space-y-2">
          <label htmlFor="difficulty" className="block text-lg font-semibold">Select Difficulty Level:</label>
          <select
            id="difficulty"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={difficulty}
            onChange={handleDifficultyChange}
            required
          >
            <option value="easy">Easy</option>
            <option value="medium">Medium</option>
            <option value="hard">Hard</option>
          </select>
        </div>

        <div className="space-y-2">
          <label htmlFor="exam-info" className="block text-lg font-semibold">Enter Exam/Class Name or College Year:</label>
          <input
            type="text"
            id="exam-info"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={examInfo}
            onChange={handleExamInfoChange}
            placeholder="E.g., Final Year Exam, College Semester 3, School Exam"
            required
          />
        </div>

        <div className="space-y-2">
          <label htmlFor="question-type" className="block text-lg font-semibold">Question Type:</label>
          <select
            id="question-type"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={questionType}
            onChange={handleQuestionTypeChange}
            required
          >
            <option value="multipleChoice">Multiple Choice</option>
            <option value="trueFalse">True/False</option>
            <option value="fillInTheBlank">Fill-in-the-Blank</option>
          </select>
        </div>

        <div className="space-y-2">
          <label htmlFor="time-limit" className="block text-lg font-semibold">Time Limit per Question (in seconds):</label>
          <input
            type="number"
            id="time-limit"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={timeLimit}
            onChange={handleTimeLimitChange}
            min={30}
            max={180}
            required
          />
        </div>

        <div className="space-y-2">
          <label htmlFor="num-questions" className="block text-lg font-semibold">Number of Questions:</label>
          <input
            type="number"
            id="num-questions"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={numQuestions}
            onChange={handleNumQuestionsChange}
            min={5}
            max={30}
            required
          />
        </div>

        <div className="flex items-center space-x-4">
          <label className="text-lg font-semibold">Include Hints:</label>
          <input
            type="checkbox"
            id="include-hint"
            checked={includeHint}
            onChange={handleIncludeHintChange}
          />
        </div>

        <div className="space-y-2">
          <label htmlFor="keywords" className="block text-lg font-semibold">Enter Custom Keywords:</label>
          <input
            type="text"
            id="keywords"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={customKeywords}
            onChange={handleKeywordsChange}
            placeholder="E.g., Algebra, Calculus, Molecules"
          />
        </div>

        <div className="space-y-2">
          <label htmlFor="study-material" className="block text-lg font-semibold">Select Study Material Type:</label>
          <select
            id="study-material"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={studyMaterialType}
            onChange={handleStudyMaterialChange}
            required
          >
            <option value="Books">Books</option>
            <option value="Videos">Videos</option>
            <option value="Notes">Notes</option>
            <option value="Articles">Articles</option>
          </select>
        </div>

        <button
          type="submit"
          className="bg-blue-600 text-white py-2 px-4 rounded-md mt-4 w-full"
        >
          Generate Quiz
        </button>
      </form>

      {formSubmitted && (
        <div className="mt-6 p-4 bg-green-100 text-green-700 rounded-md">
          <h3 className="font-semibold">Quiz Configuration Summary:</h3>
          <p><strong>Subjects:</strong> {subjects}</p>
          <p><strong>Difficulty Level:</strong> {difficulty}</p>
          <p><strong>Exam/Class Info:</strong> {examInfo}</p>
          <p><strong>Question Type:</strong> {questionType}</p>
          <p><strong>Time Limit per Question:</strong> {timeLimit} seconds</p>
          <p><strong>Number of Questions:</strong> {numQuestions}</p>
          <p><strong>Include Hints:</strong> {includeHint ? 'Yes' : 'No'}</p>
          <p><strong>Custom Keywords:</strong> {customKeywords || 'None'}</p>
          <p><strong>Study Material:</strong> {studyMaterialType}</p>
        </div>
      )}
    </div>
  );
};

export default QuizConfigPage;
